import pdfplumber
import pandas as pd
import json
import numpy as np

# Extract from PDF
pdf_data = []
with pdfplumber.open("employees_backup.pdf") as pdf:
    for page in pdf.pages:
        table = page.extract_table()
        if table:
            headers = table[0]
            for row in table[1:]:
                pdf_data.append(dict(zip(headers, row)))

pdf_df = pd.DataFrame(pdf_data)

# Read from Excel
excel_df = pd.read_excel("employees_current.xlsx")

# Convert types for comparison
pdf_df["ID"] = pdf_df["ID"].astype(str).str.strip()
excel_df["ID"] = excel_df["ID"].astype(str).str.strip()

numeric_fields = ["Salary", "Years", "Score"]
for col in numeric_fields:
    if col in pdf_df.columns:
        pdf_df[col] = pd.to_numeric(pdf_df[col], errors="coerce")
    if col in excel_df.columns:
        excel_df[col] = pd.to_numeric(excel_df[col], errors="coerce")

# 1. Deleted employees
pdf_ids = set(pdf_df["ID"])
excel_ids = set(excel_df["ID"])
deleted_employees = sorted(list(pdf_ids - excel_ids))

# 2. Modified employees
modified_employees = []
common_ids = sorted(list(pdf_ids & excel_ids))

fields_to_compare = ["First", "Last", "Dept", "Position", "Salary", "Years", "Location", "Score"]

for emp_id in common_ids:
    old_row = pdf_df[pdf_df["ID"] == emp_id].iloc[0]
    new_row = excel_df[excel_df["ID"] == emp_id].iloc[0]

    for field in fields_to_compare:
        old_val = old_row[field]
        new_val = new_row[field]

        # Handle potential NaN
        if pd.isna(old_val) and pd.isna(new_val):
            continue

        is_modified = False
        if isinstance(old_val, (int, float, np.integer, np.floating)) and isinstance(new_val, (int, float, np.integer, np.floating)):
            if abs(old_val - new_val) > 1e-9:
                is_modified = True
        else:
            if str(old_val) != str(new_val):
                is_modified = True

        if is_modified:
            out_old = old_val
            out_new = new_val

            # Convert to native Python types
            if hasattr(out_old, "item"): out_old = out_old.item()
            if hasattr(out_new, "item"): out_new = out_new.item()

            # Clean up floats to ints if they are whole numbers
            if isinstance(out_old, (int, float)) and not pd.isna(out_old):
                if out_old == int(out_old):
                    out_old = int(out_old)
            if isinstance(out_new, (int, float)) and not pd.isna(out_new):
                if out_new == int(out_new):
                    out_new = int(out_new)

            # Ensure text fields are strings
            if field not in numeric_fields:
                out_old = str(out_old) if not pd.isna(out_old) else ""
                out_new = str(out_new) if not pd.isna(out_new) else ""

            modified_employees.append({
                "id": emp_id,
                "field": field,
                "old_value": out_old,
                "new_value": out_new
            })

# Sort modified_employees by ID as requested
modified_employees.sort(key=lambda x: (x["id"], x["field"]))

result = {
    "deleted_employees": deleted_employees,
    "modified_employees": modified_employees
}

# Final check to ensure all values are serializable
def make_serializable(obj):
    if isinstance(obj, (np.integer, np.floating)):
        return obj.item()
    if isinstance(obj, np.ndarray):
        return obj.tolist()
    return obj

# Re-traverse and convert
result["modified_employees"] = [
    {k: make_serializable(v) for k, v in item.items()}
    for item in result["modified_employees"]
]

with open("diff_report.json", "w") as f:
    json.dump(result, f, indent=2)
'

